class CacheManager{constructor(e="1.0.0"){this.version=e,this.maxCacheSize=50,this.maxCacheAge=6048e5}getCacheName(){return`pwa-cache-v${this.version}`}async addToCache(e,a){try{const t=await caches.open(e);await t.addAll(a)}catch(e){throw console.error("Failed to add resources to cache:",e),e}}async cleanOldCaches(){try{const e=await caches.keys(),a=this.getCacheName(),t=e.filter(e=>e.startsWith("pwa-cache-v")&&e!==a).map(e=>caches.delete(e));await Promise.all(t)}catch(e){throw console.error("Failed to clean old caches:",e),e}}async enforceCacheLimits(e){try{const a=await caches.open(e),t=await a.keys();if(t.length<=this.maxCacheSize)return;const c=await Promise.all(t.map(async e=>{const t=await a.match(e),c=t?.headers.get("x-cache-timestamp")||"0";return{request:e,timestamp:parseInt(c,10)}}));c.sort((e,a)=>e.timestamp-a.timestamp);const s=c.slice(0,t.length-this.maxCacheSize).map(e=>a.delete(e.request));await Promise.all(s)}catch(e){throw console.error("Failed to enforce cache limits:",e),e}}async clearExpiredEntries(e){try{const a=await caches.open(e),t=await a.keys(),c=Date.now(),s=[];for(const e of t){const t=await a.match(e),r=t?.headers.get("x-cache-timestamp");if(r){c-parseInt(r,10)>this.maxCacheAge&&s.push(a.delete(e))}}await Promise.all(s)}catch(e){throw console.error("Failed to clear expired entries:",e),e}}}"undefined"!=typeof module&&module.exports&&(module.exports=CacheManager);